{"code":"import time
from onbellek import onbellekle

calls = []

@onbellekle()
def f(a, b=1, c=2):
    calls.append((a, b, c))
    return (a, b, c)

assert f(1, b=2, c=3) == (1, 2, 3)
assert f(1, c=3, b=2) == (1, 2, 3), "sıra önemsiz"
print("A ok:", calls, f.bilgi())

calls2 = []
@onbellekle()
def g(a):
    calls2.append(a)
    return a

g(1); g(1)
print("B ok: g.calls2=", calls2, "g.bilgi=", g.bilgi())
print("f.bilgi=", f.bilgi())
assert calls2 == [1], calls2
assert g.bilgi() == {"isabet": 1, "iska": 1}
assert f.bilgi() == {"isabet": 1, "iska": 1}, "başka fonksiyonun önbelleği temizlenmemeli"
print("C ok")
"}

