@onbellekle()
def h(x):
    return len(x)
h([1, 2]); h([1, 2])
print("hashlenemez:", h.bilgi())

def p(x):
    """dok."""
    return x
q = onbellekle()(p)
print("ad:", q.__name__, "doc:", q.__doc__)

now = [0.0]
clock = lambda: now[0]
@onbellekle(ttl=10, saat=clock)
def t(x):
    return x * 2
now[0] = 0.0
assert t(1) == 2 and t(1) == 2
now[0] = 10.0
assert t(1) == 2, "tam ttl hâlâ geçerli"
now[0] = 10.000001
t(1)
print("ttl:", t.bilgi())
t.temizle()
now[0] = 100.0
t(1)
print("ttl temizle sonrası:", t.bilgi())
print("OK")
